#import <XCTest/XCTest.h>
#import "IPAddrEvidenceSource.h"

@interface PackedIPAddressTests : XCTestCase
@end

@implementation PackedIPAddressTests

- (void)testValidIPv4 {
    PackedIPv4Address *addr = [[PackedIPv4Address alloc] initWithString:@"192.168.1.10"];
    XCTAssertNotNil(addr);
    XCTAssertTrue(addr.inAddr != NULL);
}

- (void)testInvalidIPv4IsNil {
    XCTAssertNil([[PackedIPv4Address alloc] initWithString:@"not-an-ip"]);
    XCTAssertNil([[PackedIPv4Address alloc] initWithString:@"999.1.1.1"]);
}

- (void)testValidIPv6Loopback {
    PackedIPv6Address *addr = [[PackedIPv6Address alloc] initWithString:@"::1"];
    XCTAssertNotNil(addr);
}

- (void)testInvalidIPv6IsNil {
    XCTAssertNil([[PackedIPv6Address alloc] initWithString:@"gggg::1"]);
}

@end

//
//  IPv4RuleMatchTests.m
//  ControlPlaneTests
//

#import <XCTest/XCTest.h>
#import "IPAddrEvidenceSource.h"
#import "IPv4RuleType.h"

@interface IPv4RuleMatchTests : XCTestCase
@end

@implementation IPv4RuleMatchTests

- (IPAddrEvidenceSource *)sourceWithAddress:(NSString *)ip {
    IPAddrEvidenceSource *source = [[IPAddrEvidenceSource alloc] init];
    PackedIPv4Address *packed = [[PackedIPv4Address alloc] initWithString:ip];
    XCTAssertNotNil(packed);
    [source setValue:@[packed] forKey:@"packedIPv4Addresses"];
    [source setValue:@[ip] forKey:@"stringIPv4Addresses"];
    return source;
}

- (void)testSubnetMatch {
    IPAddrEvidenceSource *source = [self sourceWithAddress:@"192.168.1.50"];
    IPv4RuleType *ruleType = [[IPv4RuleType alloc] initWithEvidenceSource:source];
    NSMutableDictionary *rule = [@{
        @"parameter": @"192.168.1.0,255.255.255.0"
    } mutableCopy];
    XCTAssertTrue([ruleType doesRuleMatch:rule]);
}

- (void)testSubnetMiss {
    IPAddrEvidenceSource *source = [self sourceWithAddress:@"10.0.0.5"];
    IPv4RuleType *ruleType = [[IPv4RuleType alloc] initWithEvidenceSource:source];
    NSMutableDictionary *rule = [@{
        @"parameter": @"192.168.1.0,255.255.255.0"
    } mutableCopy];
    XCTAssertFalse([ruleType doesRuleMatch:rule]);
}

- (void)testCorruptParameterDoesNotMatch {
    IPAddrEvidenceSource *source = [self sourceWithAddress:@"192.168.1.50"];
    IPv4RuleType *ruleType = [[IPv4RuleType alloc] initWithEvidenceSource:source];
    NSMutableDictionary *rule = [@{ @"parameter": @"bad" } mutableCopy];
    XCTAssertFalse([ruleType doesRuleMatch:rule]);
}

@end

