    ToggleFTPAction *action = [[ToggleFTPAction alloc] initWithOption:@YES];
    NSString *error = nil;
    XCTAssertFalse([action execute:&error]);
    XCTAssertNotNil(error);
    XCTAssertTrue([error rangeOfString:@"FTP"].location != NSNotFound);
}

