#import <Foundation/Foundation.h>
#import <ServiceManagement/ServiceManagement.h>

NS_ASSUME_NONNULL_BEGIN

/// Wraps SMAppService.mainAppService for Start at Login.
@interface CPLoginItemService : NSObject

+ (instancetype)sharedService;

/// YES when System Settings will launch the app at login (Enabled).
- (BOOL)isEnabled;

/// Maps SMAppService status to checkbox on/off.
/// Enabled and RequiresApproval → on; NotRegistered / NotFound → off.
+ (BOOL)checkboxStateForStatus:(SMAppServiceStatus)status;

/// Current SMAppService status for the main app.
- (SMAppServiceStatus)status;

/// Enable or disable login launch. On RequiresApproval, opens Login Items settings.
/// Returns YES if the resulting checkbox state matches the requested enabled flag
/// (or RequiresApproval after a successful register attempt).
- (BOOL)setEnabled:(BOOL)enabled error:(NSError * _Nullable * _Nullable)error;

/// Opens System Settings → Login Items (macOS 13+).
+ (void)openLoginItemsSettings;

@end

NS_ASSUME_NONNULL_END

//
//  CPLoginItemService.m
//  ControlPlane
//
//  IMPORTANT: This code is intended to be compiled for the ARC mode
//

#import "CPLoginItemService.h"
#import "DSLogger.h"

@implementation CPLoginItemService

+ (instancetype)sharedService
{
    static CPLoginItemService *shared = nil;
    static dispatch_once_t onceToken;
    dispatch_once(&onceToken, ^{
        shared = [[self alloc] init];
    });
    return shared;
}

+ (BOOL)checkboxStateForStatus:(SMAppServiceStatus)status
{
    switch (status) {
        case SMAppServiceStatusEnabled:
        case SMAppServiceStatusRequiresApproval:
            return YES;
        case SMAppServiceStatusNotRegistered:
        case SMAppServiceStatusNotFound:
        default:
            return NO;
    }
}

- (SMAppService *)mainAppService
{
    return [SMAppService mainAppService];
}

- (SMAppServiceStatus)status
{
    return [[self mainAppService] status];
}

- (BOOL)isEnabled
{
    return ([self status] == SMAppServiceStatusEnabled);
}

- (BOOL)setEnabled:(BOOL)enabled error:(NSError **)error
{
    SMAppService *service = [self mainAppService];
    NSError *localError = nil;

    if (enabled) {
        if (service.status == SMAppServiceStatusEnabled) {
            return YES;
        }
        if (service.status == SMAppServiceStatusRequiresApproval) {
            [[self class] openLoginItemsSettings];
            return YES;
        }
        BOOL ok = [service registerAndReturnError:&localError];
        if (!ok) {
            DSLog(@"Failed to register login item: %@", localError);
            if (error != NULL) {
                *error = localError;
            }
            return NO;
        }
        if (service.status == SMAppServiceStatusRequiresApproval) {
            [[self class] openLoginItemsSettings];
        }
        return YES;
    }

    if (service.status == SMAppServiceStatusNotRegistered) {
        return YES;
    }
    BOOL ok = [service unregisterAndReturnError:&localError];
    if (!ok) {
        DSLog(@"Failed to unregister login item: %@", localError);
        if (error != NULL) {
            *error = localError;
        }
        return NO;
    }
    return YES;
}

+ (void)openLoginItemsSettings
{
    if (@available(macOS 13.0, *)) {
        [SMAppService openSystemSettingsLoginItems];
    }
}

@end

