    WiFiEvidenceSourceCoreWLAN *source = [self sourceWithSSID:@"OfficeWiFi"];
    NSDictionary *rule = @{ @"type": @"WiFi", @"parameter": @"OfficeWiFi" };
    XCTAssertTrue([source doesRuleMatch:rule]);
}

